// GetGatewayInstancesCmd represents the command 'tptctl get gateway-instances'
var GetGatewayInstancesCmd = &cobra.Command{
	Aliases: []string{"gateway-instance"},
	Example: "  # get all gateway instances\n  tptctl get gateway-instances\n\n  # get a specific gateway instance\n  tptctl get gateway-instance --name some-gateway-instance",
	Long:    "Get gateway instances from the system. Use --name to get a specific gateway instance.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, requestedControlPlane := GetClientContext(cmd)

		// flag validation
		if err := cli.ValidateConfigNameFlags(
			gatewayConfigPath,
			gatewayName,
			"gateway instance",
		); err != nil {
			cli.Error("flag validation failed", err)
			os.Exit(1)
		}

		switch gatewayVersion {
		case "v0":
			// load values
			gatewayInstanceConfig := config_v0.GatewayInstanceConfig{}
			if gatewayConfigPath != "" {
				configContent, err := cli.ReadConfigContent(gatewayConfigPath, gatewayStdin)
				if err != nil {
					cli.Error("failed to read config", err)
					os.Exit(1)
				}
				if err := yaml.UnmarshalStrict(configContent, &gatewayInstanceConfig); err != nil {
					cli.Error("failed to unmarshal config file yaml content", err)
					os.Exit(1)
				}
			} else if gatewayName != "" {
				gatewayInstanceConfig = config_v0.GatewayInstanceConfig{
					GatewayInstance: config_v0.GatewayInstanceValues{
						Name: &gatewayName,
					},
				}
			}

			// get gateway instances
			gatewayInstances, err := gatewayInstanceConfig.Get(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to retrieve gateway instances", err)
				os.Exit(1)
			}

			// check if gateway instance exists
			if len(*gatewayInstances) == 0 {
				cli.Info(fmt.Sprintf(
					"no gateway instances found that are currently managed by %s threeport control plane",
					requestedControlPlane,
				))
				os.Exit(0)
			}

			// write the output
			switch gatewayOutput {
			case "tabular":
				if err := outputGetv0GatewayInstancesCmd(gatewayInstances); err != nil {
					cli.Error("failed to produce output", err)
					os.Exit(1)
				}
			case "yaml":
				if err := cli.YamlObjectOutput(*gatewayInstances); err != nil {
					cli.Error("failed to produce YAML output", err)
					os.Exit(1)
				}
			case "json":
				if err := cli.JsonObjectOutput(*gatewayInstances); err != nil {
					cli.Error("failed to produce JSON output", err)
					os.Exit(1)
				}
			default:
				cli.Error("", fmt.Errorf("unrecognized output format: %s", gatewayOutput))
				os.Exit(1)
			}
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Get gateway instances from the system",
	SilenceUsage: true,
	Use:          "gateway-instances",
}

func init() {
	GetCmd.AddCommand(GetGatewayInstancesCmd)

	GetGatewayInstancesCmd.Flags().StringVarP(
		&gatewayName,
		"name", "n", "", "Name of gateway instance.",
	)
	GetGatewayInstancesCmd.Flags().StringVarP(
		&gatewayConfigPath,
		"config", "c", "", "Path to file with gateway instance config.",
	)
	GetGatewayInstancesCmd.Flags().StringVarP(
		&gatewayVersion,
		"version", "v", "v0", "Version of gateway instance objects to retrieve. One of: [v0]",
	)
	GetGatewayInstancesCmd.Flags().StringVarP(
		&gatewayOutput,
		"output", "o", "tabular", "Output format for gateway instance objects. One of: [tabular, yaml, json]",
	)
	GetGatewayInstancesCmd.Flags().StringVarP(
		&cliArgs.ControlPlaneName,
		"control-plane-name", "i", "", "Optional. Name of control plane. Will default to current control plane if not provided.",
	)
}

